package com.medicinemanager.controller;
import com.medicinemanager.dto.*;import com.medicinemanager.mapper.EntityMapper;import com.medicinemanager.service.UnitService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;import java.net.URI;
@RestController @RequestMapping("/api/units") public class UnitController{private final UnitService s;private final EntityMapper m;public UnitController(UnitService s,EntityMapper m){this.s=s;this.m=m;}@PostMapping ResponseEntity<Responses.UnitResponse> create(@Valid @RequestBody Requests.UnitRequest x){var created=s.create(x);return ResponseEntity.created(URI.create("/api/units/"+created.getId())).body(m.unit(created));}@GetMapping List<Responses.UnitResponse> all(){return s.findAll().stream().map(m::unit).toList();}@GetMapping("/{id}") Responses.UnitResponse one(@PathVariable UUID id){return m.unit(s.find(id));}@PutMapping("/{id}") Responses.UnitResponse update(@PathVariable UUID id,@Valid @RequestBody Requests.UnitRequest x){return m.unit(s.update(id,x));}@DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable UUID id){s.delete(id);return ResponseEntity.noContent().build();}}
